   stack=[(r,c)];seen.add((r,c)); cells=[]
   while stack:
    a,b=stack.pop();cells.append((a,b))
    for p,q in ((a+1,b),(a-1,b),(a,b+1),(a,b-1)):
     if 0<=p<H and 0<=q<W and grid[p][q]==v and (p,q) not in seen: seen.add((p,q));stack.append((p,q))
   objs.append((v,cells))
objs=sorted(objs,key=lambda o:max(c for r,c in o[1]),reverse=True)
placed=[]
for v,cells in objs:
 shift=0
 while all(c+shift+1<W and all((r,c+shift+1)!=(rr,cc) for vv,other in placed for rr,cc in other) for r,c in cells): shift+=1
 placed.append((v,[(r,c+shift) for r,c in cells]))
out=[[0]*W for _ in range(H)]
for v,cells in placed:
 for r,c in cells:out[r][c]=v
